script:
frappe.ui.form.on('Target Detail Item', {
	    target_qty: function(frm, cdt, cdn) {
        let row = locals[cdt][cdn];

        if (!row.item || !row.target_qty) {
            row.target_amount = 0;
            frm.refresh_field('custom_targets_items');
            return;
        }

        // Get item price from Item Price
        frappe.db.get_value(
            'Item Price',
            {
                item_code: row.item,
                selling: 1   // or remove if you want any price
            },
            'price_list_rate'
        ).then(r => {
            if (r.message) {
                let price = r.message.price_list_rate || 0;
                row.target_amount = row.target_qty * price;
                frm.refresh_field('custom_targets_items');
            }
        });
    },

    item: function(frm, cdt, cdn) {
        let row = locals[cdt][cdn];

        if (!row.item || !row.target_qty) {
            row.target_amount = 0;
            frm.refresh_field('custom_targets_items');
            return;
        }

        // Get item price from Item Price
        frappe.db.get_value(
            'Item Price',
            {
                item_code: row.item,
                selling: 1   // or remove if you want any price
            },
            'price_list_rate'
        ).then(r => {
            if (r.message) {
                let price = r.message.price_list_rate || 0;
                row.target_amount = row.target_qty * price;
                frm.refresh_field('custom_targets_items');
            }
        });
    }
});

